import 'package:flutter/material.dart';
import '../models/text_analysis_models.dart';
import '../theme/app_theme.dart';

/// GeminiResultsCard displays Cloud AI analysis generated by Google Gemini.
///
/// Step 3: Displaying Results & Handling States
/// - Renders Executive Summary, Key Takeaways, Recommended Actions, and Tone Badge.
/// - Manages Loading Skeleton & Error Boundaries gracefully.
class GeminiResultsCard extends StatelessWidget {
  final GeminiInsight? insight;
  final bool isLoading;
  final String? error;
  final VoidCallback? onRetry;
  final VoidCallback? onConfigureKey;

  const GeminiResultsCard({
    super.key,
    required this.insight,
    required this.isLoading,
    required this.error,
    this.onRetry,
    this.onConfigureKey,
  });

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final cardBg = isDark ? AppTheme.xDarkCard : AppTheme.xLightCard;
    final borderColor = isDark ? AppTheme.xDarkBorder : AppTheme.xLightBorder;

    return Container(
      decoration: BoxDecoration(
        color: cardBg,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: borderColor, width: 1),
      ),
      child: Padding(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            // Card Header
            Row(
              children: [
                Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: AppTheme.xCloudPurple.withAlpha(30),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: const Icon(
                    Icons.auto_awesome,
                    color: AppTheme.xCloudPurple,
                    size: 20,
                  ),
                ),
                const SizedBox(width: 12),
                const Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Cloud AI Insights',
                        style: TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      Text(
                        'Google Gemini 3.1 Flash-Lite',
                        style: TextStyle(
                          fontSize: 12,
                          color: Colors.grey,
                        ),
                      ),
                    ],
                  ),
                ),
                if (insight != null && !isLoading && error == null)
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                    decoration: BoxDecoration(
                      color: AppTheme.xCloudPurple.withAlpha(25),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(
                        color: AppTheme.xCloudPurple.withAlpha(60),
                      ),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Icon(
                          Icons.style_outlined,
                          size: 14,
                          color: AppTheme.xCloudPurple,
                        ),
                        const SizedBox(width: 4),
                        Text(
                          insight!.tone,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w600,
                            color: AppTheme.xCloudPurple,
                          ),
                        ),
                      ],
                    ),
                  ),
              ],
            ),

            const Divider(height: 24),

            // Card Body (Loading / Error / Idle / Success)
            if (isLoading)
              _buildLoadingState()
            else if (error != null)
              _buildErrorState(context)
            else if (insight != null)
              _buildSuccessState(context)
            else
              _buildIdleState(),
          ],
        ),
      ),
    );
  }

  Widget _buildLoadingState() {
    return const Padding(
      padding: EdgeInsets.symmetric(vertical: 36),
      child: Center(
        child: Column(
          children: [
            SizedBox(
              width: 32,
              height: 32,
              child: CircularProgressIndicator(
                strokeWidth: 3,
                color: AppTheme.xCloudPurple,
              ),
            ),
            SizedBox(height: 16),
            Text(
              'Summarizing & Extracting Insights...',
              style: TextStyle(
                fontWeight: FontWeight.w600,
                color: AppTheme.xCloudPurple,
              ),
            ),
            SizedBox(height: 4),
            Text(
              'Calling Gemini via googleai_dart SDK',
              style: TextStyle(fontSize: 12, color: Colors.grey),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildErrorState(BuildContext context) {
    final isMissingKey = error!.toLowerCase().contains('key') || error!.toLowerCase().contains('missing');

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: AppTheme.xDangerRed.withAlpha(20),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: AppTheme.xDangerRed.withAlpha(50)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                const Icon(Icons.error_outline, color: AppTheme.xDangerRed),
                const SizedBox(width: 8),
                Text(
                  isMissingKey ? 'API Key Required' : 'Gemini Error',
                  style: const TextStyle(
                    fontWeight: FontWeight.bold,
                    color: AppTheme.xDangerRed,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              error!,
              style: const TextStyle(fontSize: 13),
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                if (isMissingKey && onConfigureKey != null)
                  ElevatedButton.icon(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: AppTheme.xBlue,
                      foregroundColor: Colors.white,
                    ),
                    onPressed: onConfigureKey,
                    icon: const Icon(Icons.key, size: 16),
                    label: const Text('Set Gemini Key'),
                  )
                else if (onRetry != null)
                  OutlinedButton.icon(
                    onPressed: onRetry,
                    icon: const Icon(Icons.refresh, size: 16),
                    label: const Text('Retry'),
                  ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildIdleState() {
    return const Padding(
      padding: EdgeInsets.symmetric(vertical: 36),
      child: Center(
        child: Column(
          children: [
            Icon(Icons.auto_awesome_outlined, size: 36, color: Colors.grey),
            SizedBox(height: 10),
            Text(
              'Press "Analyze Text" to generate Gemini insights.',
              textAlign: TextAlign.center,
              style: TextStyle(color: Colors.grey, fontSize: 13),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSuccessState(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Summary Box
        const Text(
          'SUMMARY',
          style: TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.bold,
            letterSpacing: 1.1,
            color: AppTheme.xCloudPurple,
          ),
        ),
        const SizedBox(height: 6),
        Container(
          width: double.infinity,
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: AppTheme.xCloudPurple.withAlpha(12),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: AppTheme.xCloudPurple.withAlpha(30)),
          ),
          child: Text(
            insight!.summary,
            style: const TextStyle(
              fontSize: 14,
              height: 1.4,
            ),
          ),
        ),

        const SizedBox(height: 16),

        // Key Insights
        if (insight!.keyInsights.isNotEmpty) ...[
          const Text(
            'KEY TAKEAWAYS',
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.bold,
              letterSpacing: 1.1,
              color: AppTheme.xCloudPurple,
            ),
          ),
          const SizedBox(height: 6),
          ...insight!.keyInsights.map(
            (item) => Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Padding(
                    padding: EdgeInsets.only(top: 2),
                    child: Icon(
                      Icons.check_circle_outline,
                      size: 16,
                      color: AppTheme.xCloudPurple,
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      item,
                      style: const TextStyle(fontSize: 13),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],

        // Action Items
        if (insight!.actionItems.isNotEmpty) ...[
          const SizedBox(height: 12),
          const Text(
            'RECOMMENDED ACTIONS',
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.bold,
              letterSpacing: 1.1,
              color: AppTheme.xWarningYellow,
            ),
          ),
          const SizedBox(height: 6),
          ...insight!.actionItems.map(
            (action) => Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Padding(
                    padding: EdgeInsets.only(top: 2),
                    child: Icon(
                      Icons.arrow_forward_rounded,
                      size: 14,
                      color: AppTheme.xWarningYellow,
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      action,
                      style: const TextStyle(fontSize: 13),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ],
    );
  }
}
